// DocumentTemplateKinds is the resolver for the documentTemplateKinds field.
//
// The catalog is the list surface: kinds are registry-driven and fixed in
// cardinality, and most have no row until an administrator customizes one, so a
// table would render empty for a feature that is mostly "system default in
// effect".
func (r *queryResolver) DocumentTemplateKinds(ctx context.Context) ([]*gqlmodel.DocumentTemplateKind, error) {
	authCtx, err := r.requirePermission(
		ctx, permission.ResourceDocumentTemplate, permission.OpRead,
	)
	if err != nil {
		return nil, err
	}

	registry := r.documentTemplateService.Registry()
	definitions := registry.All()

	out := make([]*gqlmodel.DocumentTemplateKind, 0, len(definitions))
	for _, def := range definitions {
		entry := documentTemplateKindToModel(def, registry.RequiredPaths(def.Kind))

		// Resolution answers "what does this organization actually send today",
		// which is what the card badge reports. A kind with no customization
		// resolves to the built-in and the card says so.
		resolved, rErr := r.documentTemplateService.Resolve(
			ctx,
			&services.ResolveTemplateRequest{
				TenantInfo: tenantInfo(authCtx),
				Kind:       def.Kind,
			},
		)
		if rErr != nil {
			return nil, rErr
		}
		entry.Source = resolved.Source

		if resolved.TemplateID != nil {
			template, tErr := r.documentTemplateService.Get(
				ctx,
				&repositories.GetDocumentTemplateByIDRequest{
					DocumentTemplateID:   *resolved.TemplateID,
					TenantInfo:           tenantInfo(authCtx),
					IncludeActiveVersion: true,
				},
			)
			if tErr != nil {
				return nil, tErr
			}
			entry.Template = template
		}

		out = append(out, entry)
	}

	return out, nil
}

